import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import LoginScreen from './components/LoginScreen';
import MainApp from './components/MainApp';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const handleLogin = useCallback(() => {
    setIsLoggedIn(true);
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100 transition-colors duration-300">
      {isLoggedIn ? <MainApp /> : <LoginScreen onLogin={handleLogin} />}
    </div>
  );
};

export default App;

export interface Profession {
  id: string;
  nameVI: string;
  nameEN: string;
}

export type AspectRatio = '1:1' | '16:9';

export interface ImageStyle {
  id: string;
  nameVI: string;
  promptFragment: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { AspectRatio } from '../types';

if (!process.env.API_KEY) {
  console.warn("API_KEY environment variable not set. Using a placeholder. Please set your API key.");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || 'YOUR_API_KEY_HERE' });

interface GenerateImageParams {
  base64Image: string;
  mimeType: string;
  prompt: string;
  aspectRatio: AspectRatio;
}

export const generateImage = async ({
  base64Image,
  mimeType,
  prompt,
  aspectRatio,
}: GenerateImageParams): Promise<string> => {
  try {
    const imagePart = {
      inlineData: {
        data: base64Image,
        mimeType: mimeType,
      },
    };

    const textPart = {
      text: prompt,
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [imagePart, textPart] },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
        },
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        const base64EncodeString: string = part.inlineData.data;
        return `data:${part.inlineData.mimeType};base64,${base64EncodeString}`;
      }
    }

    throw new Error('Không tìm thấy dữ liệu hình ảnh trong phản hồi của AI.');

  } catch (error) {
    console.error('Lỗi khi tạo ảnh bằng Gemini:', error);
    if (error instanceof Error) {
        throw new Error(`Lỗi API: ${error.message}`);
    }
    throw new Error('Đã xảy ra lỗi không xác định trong quá trình tạo ảnh.');
  }
};

