                    {generatedImages.map((imgSrc, index) => (
                        <div key={index} className="relative group aspect-w-1 aspect-h-1">
                            <img src={imgSrc} alt={`Generated dream job ${index + 1}`} className="w-full h-full object-cover rounded-lg shadow-md border-2 border-transparent group-hover:border-yellow-400 transition-all" />
                            <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-60 transition-all duration-300 flex items-center justify-center rounded-lg">
                                <a
                                    href={imgSrc}
                                    download={`dream-job-image-${index + 1}.png`}
                                    className="opacity-0 group-hover:opacity-100 transition-opacity duration-300 inline-flex items-center px-4 py-2 border border-transparent text-sm font-bold rounded-md shadow-sm text-indigo-950 bg-yellow-400 hover:bg-yellow-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Tải về
                                </a>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}
