import Spinner from './Spinner';

// Helper component updated to be a glowing container
const Section: React.FC<{title: string; children: React.ReactNode}> = ({title, children}) => (
  <div className="p-4 rounded-xl border border-yellow-500/30 bg-black/20 shadow-[0_0_15px_rgba(234,179,8,0.2)] transition-all duration-300 hover:border-yellow-500/50 hover:shadow-[0_0_25px_rgba(234,179,8,0.4)]">
