                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    Tải về
                                </a>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}
          {!isLoading && !error && !generatedImages && (
            <div className="text-center text-gray-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="mx-auto h-20 w-20 text-gray-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
              <p className="mt-4 text-lg font-medium">Kết quả của bạn sẽ xuất hiện ở đây</p>
              <p className="text-sm">Hãy điền thông tin và nhấn "Tạo ảnh" để bắt đầu.</p>
            </div>
          )}
        </div>
      </div>
      <footer className="text-center mt-10 py-4">
        <p className="text-sm text-gray-500">
          @2025 By Lovele - 0971738589
        </p>
      </footer>
    </div>
  );
};

export default MainApp;

import React, { useState } from 'react';
import MainApp from './components/MainApp';
import LoginScreen from './components/LoginScreen';

const App: React.FC = () => {
